#!/usr/bin/env bash
set -euo pipefail

# ── launch-simulator.sh ─────────────────────────────────────────────
# Build an iOS project and launch it on the Simulator.
# Auto-detects scheme/project/simulator, builds, installs, and launches.
#
# Exit codes:
#   0 = app launched successfully
#   1 = build failed (compile errors)
#   2 = timed out
#   3 = setup error (no project found, no scheme, etc.)
#   4 = install/launch failed
#
# Usage:
#   ./launch-simulator.sh --project-dir /path/to/project [--scheme MyApp] \
#     [--destination 'iPhone 16 Pro'] [--timeout 180] [--force-build] [--skip-build]
#
# Build modes:
#   (default)      auto-detect: build only if sources changed since last build
#   --force-build  always build, even if app is up to date
#   --skip-build   never build, just boot + install + launch last built app
# ────────────────────────────────────────────────────────────────────

PROJECT_DIR=""
SCHEME=""
TIMEOUT=180
DESTINATION=""
BUILD_MODE="auto"  # auto | force | skip

# ── Parse args ─────────────────────────────────────────────────────
while [[ $# -gt 0 ]]; do
  case "$1" in
    --project-dir)  PROJECT_DIR="$2"; shift 2 ;;
    --scheme)       SCHEME="$2"; shift 2 ;;
    --timeout)      TIMEOUT="$2"; shift 2 ;;
    --destination)  DESTINATION="$2"; shift 2 ;;
    --force-build)  BUILD_MODE="force"; shift ;;
    --skip-build)   BUILD_MODE="skip"; shift ;;
    *) echo "LAUNCH_STATUS:ERROR"; echo "Unknown arg: $1"; exit 3 ;;
  esac
done

if [[ -z "$PROJECT_DIR" ]]; then
  echo "LAUNCH_STATUS:ERROR"
  echo "Missing --project-dir"
  exit 3
fi

cd "$PROJECT_DIR"

# ── Auto-detect .xcworkspace or .xcodeproj ───────────────────────
WORKSPACE=$(find . -maxdepth 1 -name "*.xcworkspace" -type d | head -1)
XCODEPROJ=$(find . -maxdepth 1 -name "*.xcodeproj" -type d | head -1)

TARGET_FILE=""
TARGET_FLAG=""

if [[ -n "$WORKSPACE" ]]; then
  TARGET_FILE="$PROJECT_DIR/$(basename "$WORKSPACE")"
  TARGET_FLAG="-workspace"
elif [[ -n "$XCODEPROJ" ]]; then
  TARGET_FILE="$PROJECT_DIR/$(basename "$XCODEPROJ")"
  TARGET_FLAG="-project"
else
  echo "LAUNCH_STATUS:ERROR"
  echo "No .xcworkspace or .xcodeproj found in $PROJECT_DIR"
  exit 3
fi

# ── Auto-detect scheme if not provided ─────────────────────────────
if [[ -z "$SCHEME" ]]; then
  SCHEME=$(xcodebuild "$TARGET_FLAG" "$TARGET_FILE" -list 2>/dev/null \
    | awk '/Schemes:/{found=1; next} found && NF{gsub(/^[ \t]+/,""); print; exit}') || true
  if [[ -z "$SCHEME" ]]; then
    echo "LAUNCH_STATUS:ERROR"
    echo "Could not auto-detect scheme from $TARGET_FILE"
    exit 3
  fi
fi

# ── Auto-detect destination if not provided ────────────────────────
if [[ -z "$DESTINATION" ]]; then
  DESTINATION=$(xcrun simctl list devices available -j 2>/dev/null \
    | python3 -c "
import json, sys
data = json.load(sys.stdin)
for runtime, devices in sorted(data['devices'].items(), reverse=True):
    for d in devices:
        if d['isAvailable'] and 'iPhone' in d['name']:
            print(d['name']); sys.exit(0)
sys.exit(1)
" 2>/dev/null) || true
  if [[ -z "$DESTINATION" ]]; then
    echo "LAUNCH_STATUS:ERROR"
    echo "No available iPhone simulator found"
    exit 3
  fi
fi

# ── Get simulator UDID ─────────────────────────────────────────────
DEVICE_UDID=$(xcrun simctl list devices available -j 2>/dev/null \
  | python3 -c "
import json, sys
name = '$DESTINATION'
data = json.load(sys.stdin)
for runtime, devices in sorted(data['devices'].items(), reverse=True):
    for d in devices:
        if d['isAvailable'] and d['name'] == name:
            print(d['udid']); sys.exit(0)
sys.exit(1)
" 2>/dev/null) || true

if [[ -z "$DEVICE_UDID" ]]; then
  echo "LAUNCH_STATUS:ERROR"
  echo "Could not find UDID for simulator '$DESTINATION'"
  exit 3
fi

# ── Setup log file ─────────────────────────────────────────────────
LOG_DIR="$PROJECT_DIR/.locofy/agent/build-logs"
mkdir -p "$LOG_DIR"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
LOG_FILE="$LOG_DIR/launch_${TIMESTAMP}.log"

out() {
  echo "$@" | tee -a "$LOG_FILE"
}

out "LAUNCH_CONFIG:project=$TARGET_FILE"
out "LAUNCH_CONFIG:scheme=$SCHEME"
out "LAUNCH_CONFIG:destination=$DESTINATION"
out "LAUNCH_CONFIG:udid=$DEVICE_UDID"
out "LAUNCH_CONFIG:timeout=${TIMEOUT}s"
out "LAUNCH_CONFIG:build_mode=$BUILD_MODE"
out "---"

# ── Helper: timeout wrapper ───────────────────────────────────────
timeout_cmd() {
  local secs=$1; shift
  if command -v gtimeout &>/dev/null; then
    gtimeout "$secs" "$@"
  else
    perl -e '
      alarm shift @ARGV;
      $SIG{ALRM} = sub { kill "TERM", $pid; exit 142 };
      $pid = fork();
      if ($pid == 0) { exec @ARGV; die "exec: $!" }
      waitpid($pid, 0);
      exit ($? >> 8);
    ' "$secs" "$@"
  fi
}

# ── Determine if build is needed ──────────────────────────────────
NEEDS_BUILD=false

if [[ "$BUILD_MODE" == "force" ]]; then
  NEEDS_BUILD=true
elif [[ "$BUILD_MODE" == "skip" ]]; then
  NEEDS_BUILD=false
else
  # Auto-detect: compare newest .swift source against existing .app
  # Get BUILT_PRODUCTS_DIR first (needed later anyway)
  AUTO_BUILD_DIR=$(xcodebuild "$TARGET_FLAG" "$TARGET_FILE" \
    -scheme "$SCHEME" \
    -destination "platform=iOS Simulator,id=$DEVICE_UDID" \
    -configuration Debug \
    -showBuildSettings 2>/dev/null \
    | awk '/^ *BUILT_PRODUCTS_DIR = /{sub(/.*BUILT_PRODUCTS_DIR = /,""); print; exit}') || true

  AUTO_APP=$(find "${AUTO_BUILD_DIR:-/dev/null}" -maxdepth 1 -name "*.app" -type d 2>/dev/null | head -1)

  if [[ -z "$AUTO_APP" || ! -d "$AUTO_APP" ]]; then
    out "No existing build found — build required."
    NEEDS_BUILD=true
  else
    # Get .app modification time (seconds since epoch)
    APP_MTIME=$(stat -f%m "$AUTO_APP" 2>/dev/null || stat -c%Y "$AUTO_APP" 2>/dev/null || echo "0")
    # Find newest .swift file modification time
    NEWEST_SRC=$(find "$PROJECT_DIR" -name "*.swift" -not -path "*/DerivedData/*" -not -path "*/.build/*" \
      -exec stat -f%m {} \; 2>/dev/null | sort -rn | head -1)
    NEWEST_SRC=${NEWEST_SRC:-0}

    if [[ "$NEWEST_SRC" -gt "$APP_MTIME" ]]; then
      out "Sources changed since last build — build required."
      NEEDS_BUILD=true
    else
      out "App is up to date — skipping build."
      NEEDS_BUILD=false
    fi
  fi
fi

# ── Build (if needed) ─────────────────────────────────────────────
if [[ "$NEEDS_BUILD" == "true" ]]; then
  out "Building..."

  BUILD_EXIT=0
  timeout_cmd "$TIMEOUT" \
    xcodebuild \
      "$TARGET_FLAG" "$TARGET_FILE" \
      -scheme "$SCHEME" \
      -destination "platform=iOS Simulator,id=$DEVICE_UDID" \
      -configuration Debug \
      build \
    >> "$LOG_FILE" 2>&1 || BUILD_EXIT=$?

  if [[ $BUILD_EXIT -eq 124 || $BUILD_EXIT -eq 142 ]]; then
    out "LAUNCH_STATUS:TIMEOUT"
    out "Build timed out after ${TIMEOUT}s"
    exit 2
  elif [[ $BUILD_EXIT -ne 0 ]]; then
    out "LAUNCH_STATUS:BUILD_FAILED"
    ERROR_FILE="$LOG_DIR/errors_${TIMESTAMP}.txt"
    grep -E ':\d+:\d+: (error|fatal error):' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
    if [[ ! -s "$ERROR_FILE" ]]; then
      grep -E '(linker error|undefined symbol|Undefined symbols)' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
    fi
    if [[ -s "$ERROR_FILE" ]]; then
      ERROR_COUNT=$(wc -l < "$ERROR_FILE" | tr -d ' ')
      out "ERRORS_FILE:$ERROR_FILE"
      out "ERROR_COUNT:$ERROR_COUNT"
      head -20 "$ERROR_FILE"
    else
      rm -f "$ERROR_FILE"
      out "Build failed. See log: $LOG_FILE"
    fi
    exit 1
  fi

  out "Build succeeded."
fi

# ── Find the built .app bundle ─────────────────────────────────────
out "Locating built app..."

# Get DerivedData build dir from xcodebuild -showBuildSettings
BUILD_DIR=$(xcodebuild "$TARGET_FLAG" "$TARGET_FILE" \
  -scheme "$SCHEME" \
  -destination "platform=iOS Simulator,id=$DEVICE_UDID" \
  -configuration Debug \
  -showBuildSettings 2>/dev/null \
  | awk '/^ *BUILT_PRODUCTS_DIR = /{sub(/.*BUILT_PRODUCTS_DIR = /,""); print; exit}') || true

if [[ -z "$BUILD_DIR" ]]; then
  out "LAUNCH_STATUS:ERROR"
  out "Could not determine BUILT_PRODUCTS_DIR"
  exit 3
fi

APP_BUNDLE=$(find "$BUILD_DIR" -maxdepth 1 -name "*.app" -type d | head -1)

if [[ -z "$APP_BUNDLE" ]]; then
  out "LAUNCH_STATUS:ERROR"
  out "No .app bundle found in $BUILD_DIR"
  exit 3
fi

APP_BUNDLE_ID=$(/usr/libexec/PlistBuddy -c "Print :CFBundleIdentifier" "$APP_BUNDLE/Info.plist" 2>/dev/null) || true

if [[ -z "$APP_BUNDLE_ID" ]]; then
  out "LAUNCH_STATUS:ERROR"
  out "Could not read bundle ID from $APP_BUNDLE/Info.plist"
  exit 3
fi

out "LAUNCH_CONFIG:app=$APP_BUNDLE"
out "LAUNCH_CONFIG:bundle_id=$APP_BUNDLE_ID"

# ── Boot simulator ─────────────────────────────────────────────────
BOOT_STATE=$(xcrun simctl list devices -j 2>/dev/null \
  | python3 -c "
import json, sys
data = json.load(sys.stdin)
udid = '$DEVICE_UDID'
for runtime, devices in data['devices'].items():
    for d in devices:
        if d['udid'] == udid:
            print(d['state']); sys.exit(0)
print('Unknown')
" 2>/dev/null) || true

if [[ "$BOOT_STATE" != "Booted" ]]; then
  out "Booting simulator '$DESTINATION'..."
  xcrun simctl boot "$DEVICE_UDID" 2>/dev/null || true
  # Wait for boot
  for i in $(seq 1 10); do
    STATE=$(xcrun simctl list devices -j 2>/dev/null \
      | python3 -c "
import json, sys
data = json.load(sys.stdin)
for runtime, devices in data['devices'].items():
    for d in devices:
        if d['udid'] == '$DEVICE_UDID':
            print(d['state']); sys.exit(0)
" 2>/dev/null) || true
    if [[ "$STATE" == "Booted" ]]; then break; fi
    sleep 1
  done
fi

# Open Simulator.app so the user can see it
open -a Simulator 2>/dev/null || true

# ── Install app ────────────────────────────────────────────────────
out "Installing app on simulator..."
if ! xcrun simctl install "$DEVICE_UDID" "$APP_BUNDLE" >> "$LOG_FILE" 2>&1; then
  out "LAUNCH_STATUS:INSTALL_FAILED"
  out "Failed to install $APP_BUNDLE on $DESTINATION"
  exit 4
fi

# ── Terminate existing instance if running ─────────────────────────
xcrun simctl terminate "$DEVICE_UDID" "$APP_BUNDLE_ID" 2>/dev/null || true

# ── Launch app ─────────────────────────────────────────────────────
out "Launching $APP_BUNDLE_ID..."
if ! xcrun simctl launch "$DEVICE_UDID" "$APP_BUNDLE_ID" >> "$LOG_FILE" 2>&1; then
  out "LAUNCH_STATUS:INSTALL_FAILED"
  out "Failed to launch $APP_BUNDLE_ID on $DESTINATION"
  exit 4
fi

out "---"
out "LAUNCH_STATUS:SUCCESS"
out "App '$SCHEME' ($APP_BUNDLE_ID) is running on '$DESTINATION'"
exit 0
